result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/cycles.py", "content": """"Thermodynamic cycle efficiency calculator with a CLI."""

import argparse
import math
import sys


def carnot_efficiency(th: float, tc: float) -> float:
    """Carnot efficiency: 1 - Tc/Th (temperatures in Kelvin)."""
    if th <= 0 or tc <= 0:
        raise ValueError("Temperatures must be positive (Kelvin).")
    if tc > th:
        raise ValueError("Cold reservoir temperature must not exceed hot reservoir temperature.")
    return 1.0 - tc / th


def otto_efficiency(r: float, gamma: float) -> float:
    """Otto cycle efficiency: 1 - r^(1-gamma) (compression ratio r)."""
    if r <= 1:
        raise ValueError("Compression ratio must be greater than 1.")
    if gamma <= 1:
        raise ValueError("gamma must be greater than 1.")
    return 1.0 - r ** (1.0 - gamma)


def diesel_efficiency(r: float, rc: float, gamma: float) -> float:
    """Diesel cycle efficiency: 1 - r^(1-gamma) * (rc^gamma - 1) / (gamma * (rc - 1))."""
    if r <= 1:
        raise ValueError("Compression ratio must be greater than 1.")
    if rc <= 1:
        raise ValueError("Cutoff ratio must be greater than 1.")
    if gamma <= 1:
        raise ValueError("gamma must be greater than 1.")
    return 1.0 - r ** (1.0 - gamma) * (rc ** gamma - 1.0) / (gamma * (rc - 1.0))


def brayton_efficiency(pr: float, gamma: float) -> float:
    """Brayton cycle efficiency: 1 - pr^((1-gamma)/gamma) (pressure ratio pr)."""
    if pr <= 1:
        raise ValueError("Pressure ratio must be greater than 1.")
    if gamma <= 1:
        raise ValueError("gamma must be greater than 1.")
    return 1.0 - pr ** ((1.0 - gamma) / gamma)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description="Thermodynamic cycle efficiency calculator")
    sub = parser.add_subparsers(dest="cycle", required=True)

    p = sub.add_parser("carnot", help="Carnot cycle efficiency")
    p.add_argument("--th", type=float, required=True, help="Hot reservoir temperature (K)")
    p.add_argument("--tc", type=float, required=True, help="Cold reservoir temperature (K)")

    p = sub.add_parser("otto", help="Otto cycle efficiency")
    p.add_argument("--r", type=float, required=True, help="Compression ratio")
    p.add_argument("--gamma", type=float, default=1.4, help="Heat capacity ratio")

    p = sub.add_parser("diesel", help="Diesel cycle efficiency")
    p.add_argument("--r", type=float, required=True, help="Compression ratio")
    p.add_argument("--rc", type=float, required=True, help="Cutoff ratio")
    p.add_argument("--gamma", type=float, default=1.4, help="Heat capacity ratio")

    p = sub.add_parser("brayton", help="Brayton cycle efficiency")
    p.add_argument("--pr", type=float, required=True, help="Pressure ratio")
    p.add_argument("--gamma", type=float, default=1.4, help="Heat capacity ratio")

    args = parser.parse_args(argv)

    if args.cycle == "carnot":
        eta = carnot_efficiency(args.th, args.tc)
    elif args.cycle == "otto":
        eta = otto_efficiency(args.r, args.gamma)
    elif args.cycle == "diesel":
        eta = diesel_efficiency(args.r, args.rc, args.gamma)
    else:
        eta = brayton_efficiency(args.pr, args.gamma)

    print(f"{eta * 100:.2f}%")
    return 0


if __name__ == "__main__":
    sys.exit(main())
