from hypothesis import given, settings
from hypothesis import strategies as st

from cycles import brayton_efficiency, carnot_efficiency, diesel_efficiency, otto_efficiency

GAMMAS = st.floats(min_value=1.05, max_value=1.8)


def test_carnot_exact():
    assert carnot_efficiency(500, 300) == 1 - 300 / 500


@given(
    th=st.floats(min_value=301, max_value=2000),
    tc=st.floats(min_value=100, max_value=300),
)
def test_carnot_property(th, tc):
    eta = carnot_efficiency(th, tc)
    assert 0 < eta < 1


@given(r=st.floats(min_value=1.5, max_value=25), gamma=GAMMAS)
def test_otto_property(r, gamma):
    eta = otto_efficiency(r, gamma)
    assert 0 < eta < 1


@given(
    r=st.floats(min_value=2, max_value=25),
    rc=st.floats(min_value=1.2, max_value=4),
    gamma=GAMMAS,
)
def test_diesel_property(r, rc, gamma):
    eta = diesel_efficiency(r, rc, gamma)
    assert 0 < eta < 1


@given(pr=st.floats(min_value=1.5, max_value=40), gamma=GAMMAS)
def test_brayton_property(pr, gamma):
    eta = brayton_efficiency(pr, gamma)
    assert 0 < eta < 1


def test_otto_sample():
    assert abs(otto_efficiency(8, 1.4) - 0.5647) < 0.01


def test_diesel_sample():
    expected = 1 - 18 ** (1 - 1.4) * (2 ** 1.4 - 1) / (1.4 * (2 - 1))
    assert abs(diesel_efficiency(18, 2, 1.4) - expected) < 0.05
    assert abs(diesel_efficiency(18, 2, 1.4) - 0.6310) < 0.005


def test_brayton_sample():
    assert abs(brayton_efficiency(10, 1.4) - 0.4822) < 0.01


@given(
    r=st.floats(min_value=1.01, max_value=30),
    tc=st.floats(min_value=150, max_value=400),
    ratio=st.sampled_from([2.0, 3.0, 5.0]),
)
@settings(max_examples=50)
def test_carnot_beats_otto_at_extreme_ratios(r, tc, ratio):
    # Otto's effective temperature ratio extremes are t = r^(1-gamma) for gamma in range;
    # Carnot with th/tc equal to that ratio beats it.
    for gamma in (1.3, 1.4, 1.6):
        otto_t_ratio = 1.0 / otto_efficiency(r, gamma)  # 1/(1 - r^(1-gamma)) >= 1
        th = tc * max(otto_t_ratio, ratio)
        assert carnot_efficiency(th, tc) > otto_efficiency(r, gamma)


def test_cli_smoke():
    cases = [
        (["carnot", "--th", "500", "--tc", "300"], "40.00%"),
        (["otto", "--r", "8", "--gamma", "1.4"], f"{otto_efficiency(8, 1.4) * 100:.2f}%"),
        (
            ["diesel", "--r", "18", "--rc", "2", "--gamma", "1.4"],
            f"{diesel_efficiency(18, 2, 1.4) * 100:.2f}%",
        ),
        (["brayton", "--pr", "10", "--gamma", "1.4"], f"{brayton_efficiency(10, 1.4) * 100:.2f}%"),
    ]
    for argv, expected in cases:
        out = subprocess.run(
            [sys.executable, "cycles.py"] + argv,
            capture_output=True,
            text=True,
            check=True,
        ).stdout.strip()
        assert out.endswith("%")
        assert out == expected, (argv, out, expected)


def test_cli_carnot_known_output():
    out = subprocess.run(
